import SwiftUI

struct HeaderView: View { @Binding var showProfile: Bool; var body: some View { HStack { HStack(spacing: 9) { Image(systemName: "scope").font(.title3.bold()).foregroundColor(Theme.accent); Text("Truth").font(.title3.bold()) + Text("Oracle").foregroundColor(Theme.accent).font(.title3.bold()) }; Spacer(); Button { showProfile = true } label: { Circle().fill(Theme.ink).frame(width: 38, height: 38).overlay(Text("AK").font(.caption.weight(.bold)).foregroundColor(.white)) } }.padding(.top, 8) } }
struct SectionTitle: View { let title: String; let action: String; var onTap: () -> Void; init(title: String, action: String, onTap: @escaping () -> Void = {}) { self.title = title; self.action = action; self.onTap = onTap }; var body: some View { HStack { Text(title).font(.title3.bold()).foregroundColor(Theme.ink); Spacer(); Button(action: onTap) { Text(action).font(.caption.bold()).foregroundColor(Theme.accent) } } } }
struct FilterPill: View { let text: String; var active = false; var body: some View { Text(text).font(.caption.bold()).foregroundColor(active ? .white : Theme.muted).padding(.horizontal, 13).padding(.vertical, 9).background(active ? Theme.ink : Color.white).clipShape(Capsule()) } }
struct WalletAction: View { let title: String; let icon: String; var body: some View { Button {} label: { Label(title, systemImage: icon).font(.subheadline.bold()).frame(maxWidth: .infinity).padding(14).background(Color.white).foregroundColor(Theme.ink).clipShape(RoundedRectangle(cornerRadius: 14)).overlay(RoundedRectangle(cornerRadius: 14).stroke(Theme.border)) } } }
struct ActivityRow: View { let title: String; let detail: String; let amount: String; let positive: Bool; var body: some View { HStack { Circle().fill(positive ? Theme.green.opacity(0.12) : Theme.red.opacity(0.12)).frame(width: 38, height: 38).overlay(Image(systemName: positive ? "checkmark" : "chart.line.uptrend.xyaxis").foregroundColor(positive ? Theme.green : Theme.red)); VStack(alignment: .leading) { Text(title).font(.subheadline.bold()); Text(detail).font(.caption).foregroundColor(Theme.muted) }; Spacer(); Text(amount).font(.subheadline.bold()).foregroundColor(positive ? Theme.green : Theme.ink) }.padding(14).background(Color.white).clipShape(RoundedRectangle(cornerRadius: 16)) } }
struct Theme { static let background = Color(red: 0.965, green: 0.973, blue: 0.98); static let ink = Color(red: 0.055, green: 0.09, blue: 0.14); static let muted = Color(red: 0.38, green: 0.44, blue: 0.52); static let border = Color.black.opacity(0.06); static let accent = Color(red: 0.08, green: 0.43, blue: 0.88); static let green = Color(red: 0.04, green: 0.58, blue: 0.36); static let red = Color(red: 0.82, green: 0.23, blue: 0.25); static let mint = Color(red: 0.48, green: 0.95, blue: 0.76); static let gradient = LinearGradient(colors: [Color(red: 0.04, green: 0.11, blue: 0.23), Color(red: 0.06, green: 0.34, blue: 0.55)], startPoint: .topLeading, endPoint: .bottomTrailing) }
struct Market: Identifiable { let id = UUID(); let title: String; let category: String; let probability: Int; let volume: String; let time: String; static let samples = [Market(title: "Will the Fed cut rates in September?", category: "Macro", probability: 68, volume: "2.4M", time: "18d left"), Market(title: "Will Bitcoin cross $120k this year?", category: "Crypto", probability: 54, volume: "1.8M", time: "126d left"), Market(title: "Will AI regulation pass before July?", category: "Technology", probability: 41, volume: "920K", time: "42d left"), Market(title: "Will India win the next test series?", category: "Sports", probability: 73, volume: "640K", time: "9d left")] }
struct NewsArticle: Identifiable { let id = UUID(); let title: String; let source: String; let time: String; let icon: String; let color: Color; static let samples = [NewsArticle(title: "Markets price in a softer path for rates", source: "Reuters", time: "12 min ago", icon: "chart.line.uptrend.xyaxis", color: .blue), NewsArticle(title: "Crypto liquidity returns as volatility cools", source: "Bloomberg", time: "1 hr ago", icon: "bitcoinsign.circle.fill", color: .orange), NewsArticle(title: "New AI framework moves through committee", source: "The Verge", time: "3 hrs ago", icon: "cpu.fill", color: .purple)] }
